package com.yihe.framework.ehr;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Presentation and explicit transaction orchestration over the established review workflow. */
@Service
public class ArchiveReviewService {
    final EhrRepository db;final EhrService ehr;final ReportMatchingService matching;
    public ArchiveReviewService(EhrRepository db,EhrService ehr,ReportMatchingService matching){this.db=db;this.ehr=ehr;this.matching=matching;}
    static String key(Object id,Object revision){return id+":"+revision;}
    String state(Map<String,Object> raw,boolean published,String stage,boolean returned){if(published)return "archived";if("confirmed".equals(raw.get("review_status")))return "ready";if("rejected".equals(raw.get("review_status")))return "rejected";if("pending_review".equals(stage))return "pending";if(returned)return "returned";return "draft";}
    String type(Map<String,Object> raw){String type=str(raw.get("exam_type_raw")).trim();return type.isEmpty()?"体检报告":type.endsWith("报告")?type:type+"报告";}
    public Map<String,Object> list(EhrActor actor,Map<String,String> query){
        require(!actor.mobile,403,"仅供后台管理使用");List<Map<String,Object>> people=matching.preparedEmployees(actor);Map<String,Map<String,Object>> states=new HashMap<>(),metadata=new HashMap<>();Map<String,String> stages=new HashMap<>(),submitted=new HashMap<>();Set<String> returns=new HashSet<>();
        for(Map<String,Object> row:db.all("SELECT * FROM a_report_matching WHERE scope_code=? AND data_mode=?",actor.scope,actor.mode))states.put(key(row.get("report_id"),row.get("revision")),row);
        for(Map<String,Object> row:db.all("SELECT report_id,revision,prior_revision,exam_type_raw,exam_number_raw,review_status FROM a_health_reports WHERE scope_code=? AND data_mode=?",actor.scope,actor.mode))metadata.put(key(row.get("report_id"),row.get("revision")),row);
        for(Map<String,Object> row:db.all("SELECT report_id,revision,status FROM a_extraction_jobs WHERE scope_code=? AND data_mode=? ORDER BY updated_at DESC,created_at DESC,job_id DESC",actor.scope,actor.mode))stages.putIfAbsent(key(row.get("report_id"),row.get("revision")),str(row.get("status")));
        for(Map<String,Object> row:db.all("SELECT report_id,revision,occurred_at FROM a_health_archive_audit_logs WHERE scope_code=? AND data_mode=? AND action='report_submitted' ORDER BY occurred_at DESC",actor.scope,actor.mode))submitted.putIfAbsent(key(row.get("report_id"),row.get("revision")),str(row.get("occurred_at")));
        for(Map<String,Object> row:db.all("SELECT v.report_id,v.revision FROM a_review_records v JOIN a_health_reports h ON h.report_id=v.report_id AND h.revision=v.revision WHERE h.scope_code=? AND h.data_mode=? AND v.decision='return'",actor.scope,actor.mode))returns.add(key(row.get("report_id"),row.get("revision")));
        String search=ReportMatchingService.norm(query.get("search")),status=str(query.get("status")),organization=str(query.get("organization")),reportType=str(query.get("type")),from=str(query.get("from")),to=str(query.get("to"));require(search.length()<=100,422,"搜索内容过长");require(status.isEmpty()||Arrays.asList("all","draft","pending","returned","ready","archived","rejected").contains(status),422,"审核状态不正确");for(String date:Arrays.asList(from,to))if(!date.isEmpty())try{java.time.LocalDate.parse(date);}catch(Exception e){throw new EhrException(422,"日期格式不正确");}
        Map<String,Object> counts=map("all",0,"draft",0,"pending",0,"returned",0,"ready",0,"archived",0,"rejected",0);List<Map<String,Object>> rows=new ArrayList<>();Set<String> types=new TreeSet<>(),units=new TreeSet<>();
        for(Map<String,Object> source:matching.reportRows(actor)){String k=key(source.get("id"),source.get("revision"));Map<String,Object> meta=metadata.get(k),enriched=matching.enrich(source,states.get(k),people);Map<String,Object> current=(Map<String,Object>)enriched.get("currentEmployee");String label=type(meta);types.add(label);if(current!=null)units.add(str(current.get("organization")));String date=str(source.get("examDate"));
            if(!reportType.isEmpty()&&!reportType.equals(label)||!organization.isEmpty()&&(current==null||!organization.equals(current.get("organization"))))continue;
            if(!from.isEmpty()&&(date.isEmpty()||date.compareTo(from)<0)||!to.isEmpty()&&(date.isEmpty()||date.compareTo(to)>0))continue;
            if(!search.isEmpty()&&!ReportMatchingService.norm(current==null?null:current.get("name")).contains(search)&&!ReportMatchingService.norm(current==null?null:current.get("code")).contains(search)&&!ReportMatchingService.norm(source.get("fileName")).contains(search)&&!ReportMatchingService.norm(source.get("id")).contains(search)&&!ReportMatchingService.norm(meta.get("exam_number_raw")).contains(search))continue;
            String reviewState=state(meta,num(source.get("published"))==1,stages.getOrDefault(k,"uploaded"),returns.contains(key(source.get("id"),meta.get("prior_revision"))));counts.put("all",num(counts.get("all"))+1);counts.put(reviewState,num(counts.get(reviewState))+1);
            enriched.put("reviewState",reviewState);enriched.put("reportType",label);enriched.put("submittedAt",submitted.get(k));enriched.remove("candidates");
            if(status.isEmpty()||status.equals("all")||status.equals(reviewState))rows.add(enriched);
        }
        int page=bounded(query.get("page"),1,1,100000),limit=bounded(query.get("limit"),10,1,100),start=Math.min(rows.size(),(page-1)*limit),end=Math.min(rows.size(),start+limit);
        return map("items",rows.subList(start,end),"total",rows.size(),"counts",counts,"page",page,"limit",limit,"types",types,"organizations",units,"canReview",actor.doctor);
    }
    @SuppressWarnings("unchecked") public Map<String,Object> detail(EhrActor actor,String id,int revision){
        require(!actor.mobile,403,"仅供后台管理使用");Map<String,Object> raw=ehr.rawReport(actor,id,revision,false),report=ehr.report(actor,id,revision,true),person=ehr.profile(actor,str(raw.get("record_id")),false);
        Map<String,Object> stage=db.one("SELECT status FROM a_extraction_jobs WHERE report_id=? AND revision=? ORDER BY updated_at DESC,job_id DESC LIMIT 1",id,revision);boolean returned=raw.get("prior_revision")!=null&&db.count("SELECT COUNT(*) FROM a_review_records WHERE report_id=? AND revision=? AND decision='return'",id,raw.get("prior_revision"))>0;
        Map<String,Object> match;int current=num(db.one("SELECT current_revision FROM a_report_series WHERE report_id=?",id).get("current_revision"));if(current==revision)match=matching.detail(actor,id,revision);else match=map("matchStatus","history","locked",true);
        List<Map<String,Object>> logs=db.all("SELECT action,reason note,CONVERT(actor_ref USING utf8mb4) actor,occurred_at time,redacted_diff changes FROM a_health_archive_audit_logs WHERE scope_code=? AND data_mode=? AND report_id=? ORDER BY occurred_at DESC,audit_id DESC LIMIT 150",actor.scope,actor.mode,id);for(Map<String,Object> log:logs)log.put("changes",ehr.decode(log.get("changes")));
        List<Map<String,Object>> versions=db.all("SELECT h.revision,h.review_status reviewStatus,h.created_at createdAt,EXISTS(SELECT 1 FROM a_report_publications p WHERE p.report_id=h.report_id AND p.revision=h.revision) published FROM a_health_reports h WHERE h.report_id=? AND h.scope_code=? AND h.data_mode=? ORDER BY h.revision DESC",id,actor.scope,actor.mode);
        Map<String,Object> fields=matching.identity(raw.get("field_values"));
        return map("report",report,"employee",map("id",raw.get("record_id"),"name",person.get("employee_name"),"code",person.get("employee_no"),"organization",person.get("organization_name"),"team",person.get("team_name"),"job",person.get("position_name"),"identity",ReportMatchingService.masked(fields.get("identity_number"))),"matching",map("status",match.get("matchStatus"),"ruleVersion",ReportMatchingService.RULE),"reviewState",state(raw,Boolean.TRUE.equals(report.get("published")),stage==null?"uploaded":str(stage.get("status")),returned),"reportType",type(raw),"logs",logs,"versions",versions,"currentRevision",current,"missing",ehr.missing(person,raw),"canReview",actor.doctor,"candidateOnly",ehr.candidateOnly);
    }
    void identity(EhrActor actor,Map<String,Object> raw){Map<String,Object> person=ehr.profile(actor,str(raw.get("record_id")),false),fields=matching.identity(raw.get("field_values"));require(((List<?>)fields.get("conflicts")).isEmpty(),422,"报告身份字段存在多值冲突，请先核对原件");require(!ReportMatchingService.norm(fields.get("full_name")).isEmpty()&&ReportMatchingService.norm(fields.get("full_name")).equals(ReportMatchingService.norm(person.get("employee_name"))),422,"报告姓名与关联职工不一致，请先完成匹配与OCR校对");String code=ReportMatchingService.norm(fields.get("employee_number"));require(code.isEmpty()||code.equals(ReportMatchingService.norm(person.get("employee_no"))),422,"报告工号与关联职工不一致，请先核对原件");}
    @Transactional public Map<String,Object> act(EhrActor actor,String id,int revision,Map<String,Object> body){
        require(!actor.mobile,403,"仅供后台管理使用");String action=text(body,"action"),request=text(body,"requestKey"),note=text(body,"note"),expected=text(body,"etag");require(Arrays.asList("submit","approve","approve_archive","archive","return").contains(action),422,"审核操作不正确");require(!request.isEmpty()&&request.length()<=80,422,"缺少有效操作幂等键");require(!note.isEmpty()&&note.length()<=600,422,"请填写600字以内处理说明");if(!action.equals("submit"))require(actor.doctor,403,"仅医生账号可执行审核、退回和归档");if(Arrays.asList("approve","approve_archive","archive").contains(action))require(!ehr.candidateOnly,403,"当前环境不允许审核或发布正式档案");
        Map<String,Object> raw=ehr.rawReport(actor,id,revision,true);String hash=hex(digest(bytes(ehr.encode(body))));Map<String,Object> prior=db.one("SELECT redacted_diff FROM a_health_archive_audit_logs WHERE scope_code=? AND data_mode=? AND report_id=? AND revision=? AND action LIKE 'review_center_%' AND request_key=? LIMIT 1",actor.scope,actor.mode,id,revision,request);
        if(prior!=null){Map<?,?> receipt=(Map<?,?>)ehr.decode(prior.get("redacted_diff"));require(hash.equals(receipt.get("payloadHash")),409,"幂等键已用于其他操作");return detail(actor,id,num(receipt.get("resultRevision")));}
        Map<String,Object> report=ehr.report(actor,id,revision,false);require(!expected.isEmpty()&&expected.equals(report.get("etag")),409,"报告内容已变化，请刷新后重新核对");require(!Boolean.TRUE.equals(report.get("published")),409,"报告已归档，不可重复审核或退回");
        if(Arrays.asList("approve","approve_archive","archive").contains(action)){require(Boolean.TRUE.equals(body.get("identityVerified"))&&Boolean.TRUE.equals(body.get("contentVerified"))&&Boolean.TRUE.equals(body.get("conflictsResolved")),422,"请逐项确认职工身份、原件与识别数据及无冲突重复报告");identity(actor,raw);}
        Map<String,Object> result;
        if(action.equals("submit"))result=ehr.transition(actor,id,revision,map("action","submit","note",note,"requestKey",request+".submit"));
        else if(action.equals("return"))result=ehr.transition(actor,id,revision,map("action","return","note",note,"requestKey",request+".return"));
        else {
            if(action.equals("approve")||action.equals("approve_archive")){
                if(!"confirmed".equals(report.get("reviewStatus"))){
                    if(!"pending_review".equals(report.get("stage")))ehr.transition(actor,id,revision,map("action","submit","note",note,"requestKey",request+".submit"));
                    Map<String,Object> fresh=ehr.report(actor,id,revision,false);ehr.transition(actor,id,revision,map("action","approve","note",note,"requestKey",request+".approve","etag",fresh.get("etag"),"identityVerified",true,"reportKindVerified",Boolean.TRUE.equals(body.get("reportKindVerified"))));
                }else require(action.equals("approve_archive"),409,"此报告已通过审核，可直接归档");
            }
            if(action.equals("archive")||action.equals("approve_archive"))ehr.transition(actor,id,revision,map("action","archive","note",note,"requestKey",request+".archive"));
            result=ehr.report(actor,id,revision,false);
        }
        int resultRevision=num(result.get("revision"));db.insert("a_health_archive_audit_logs",ehr.scoped(actor,"audit_id",id(),"record_id",result.get("recordId"),"report_id",id,"revision",revision,"actor_ref",bytes(actor.user),"action","review_center_"+action,"request_key",request,"reason",note,"redacted_diff",ehr.encode(map("payloadHash",hash,"resultRevision",resultRevision,"identityVerified",Boolean.TRUE.equals(body.get("identityVerified")),"contentVerified",Boolean.TRUE.equals(body.get("contentVerified")),"conflictsResolved",Boolean.TRUE.equals(body.get("conflictsResolved")))),"occurred_at",now()));return detail(actor,id,resultRevision);
    }
    @Transactional public Map<String,Object> batch(EhrActor actor,Map<String,Object> body){Object value=body.get("items");require(value instanceof List,422,"缺少报告清单");List<?> list=(List<?>)value;require(!list.isEmpty()&&list.size()<=50,422,"批量操作限1至50份报告");List<Map<String,Object>> items=new ArrayList<>();for(Object row:list){require(row instanceof Map,422,"报告清单格式不正确");items.add(new LinkedHashMap<>((Map<String,Object>)row));}items.sort(Comparator.comparing(row->text(row,"reportId")));Set<String> unique=new HashSet<>();List<Object> results=new ArrayList<>();for(Map<String,Object> row:items){String id=text(row,"reportId");int revision=num(row.get("revision"));require(unique.add(key(id,revision)),422,"清单中存在重复报告");Map<String,Object> request=new LinkedHashMap<>(body);request.remove("items");request.putAll(row);results.add(act(actor,id,revision,request));}return map("processed",results.size(),"items",results,"atomic",true);}
}
